local UINightCatInstanceBuffInfoNode = Class('UINightCatInstanceBuffInfoNode')

function UINightCatInstanceBuffInfoNode:__init()
    self._buffId = nil
    self._cb = nil

end

function UINightCatInstanceBuffInfoNode:__delete()
    self._buffId = nil
    self._cb = nil

end

function UINightCatInstanceBuffInfoNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnUpLevel))
    SetButtonAction(self.FontStyleButton2, Bind(self, self.OnBtnRemove))
    SetButtonAction(self.FontStyleButton3, Bind(self, self.OnBtnEquip))
end

---Refresh
---@param data table 
function UINightCatInstanceBuffInfoNode:Refresh(buffId, cb)
    if not buffId then
        return
    end
    self._buffId = buffId
    self._cb = cb

    self:FillSelf()
end

function UINightCatInstanceBuffInfoNode:FillSelf()
    local vo = QuestConfMgr:GetInstance():GetNightCatGoodsVo(self._buffId)
    if not vo then
        return
    end

    local isUnlock = QuestConfMgr:GetInstance():IsUnlockNightCatBuff(self._buffId)
    local isEquip = comp:IsEquipBuff(self._buffId)
    
    CfUtils.SetActive(self.StatusNotGet, not isUnlock)
    CfUtils.SetActive(self.StatusHasGet, isUnlock)

    CfUtils.SetActive(self.UnlockMethodNode, not isUnlock)
    CfUtils.SetActive(self.BtnNode, isUnlock)

    CfUtils.FillText(self.TextName, vo.name)
    CfUtils.FillText(self.TextDesc2, vo.description)
    CfUtils.SetActive(self.TextDesc2, isUnlock)

    CfUtils.SetActive(self.TextDesc1, true)

    if isUnlock then
        local isMaxLevel = comp:IsBuffMaxLevel(self._buffId)
        local level = comp:GetBuffLevel(self._buffId)

        --满级
        if isMaxLevel then
            CfUtils.FillText(self.TextLevel, "MAX")
        else
            CfUtils.FillText(self.TextLevel, "Lv."..level)
            local t = QuestConfMgr:GetInstance():GetNightCatBuffUpLevelConsume(self._buffId, level + 1)
            if t then
                CfUtils.FillImage(self.Image, GoodsConfMgr:GetInstance():GetPhotoPathById(t.goodsId))
                CfUtils.FillText(self.Text2, "x"..t.num)
            end
        end

        CfUtils.FillImage(self.ImgIcon, vo.photoId)
        CfUtils.FillImage(self.ImgIcon2, vo.photoId)
        CfUtils.SetActive(self.StatusEquip, isEquip)

        CfUtils.SetActive(self.FontStyleButton3, not isEquip)
        CfUtils.SetActive(self.FontStyleButton2, isEquip)
        CfUtils.SetActive(self.UngradeNode, not isMaxLevel)      
        
        local tableName = string.format("%sIDGroup", AutoIds.IdSetting2731)
        local effectId = CfUtils.GetStringIdGroupData(tableName, self._buffId.."_"..level)
        local effectVo = QuestConfMgr:GetInstance():GetNightCatGoodsEffectVo(effectId)
        CfUtils.FillText(self.TextDesc1, effectVo.desc)

        local questUpBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(effectId) or {}
        CfUtils.FillText(self.TextNumber, string.fmt('+%1', checkInt(questUpBuffVo.combatValue1)))
    else
        local tableName = string.format("%sIDGroup", AutoIds.IdSetting2731)
        local effectId = CfUtils.GetStringIdGroupData(tableName, self._buffId.."_"..1)
        local effectVo = QuestConfMgr:GetInstance():GetNightCatGoodsEffectVo(effectId)
        CfUtils.FillText(self.TextDesc1, effectVo.desc)
        CfUtils.FillText(self.TextNumber, '')

        local plotVo = QuestConfMgr:GetInstance():GetNightCatPlotVo(vo.plotId)
        if plotVo then
            CfUtils.FillText(self.Text, localize("通关_name_解锁", {_name_ = plotVo.name}))
        end
    end
end

--升级
function UINightCatInstanceBuffInfoNode:OnBtnUpLevel()
    local isOpne = comp:IsOpen()
    if not isOpne then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockNightCatBuff(self._buffId)
    if not isUnlock then
        return
    end
    local isMaxLevel = comp:IsBuffMaxLevel(self._buffId)
    if isMaxLevel then
        return
    end

    local level = comp:GetBuffLevel(self._buffId)
    local t = QuestConfMgr:GetInstance():GetNightCatBuffUpLevelConsume(self._buffId, level + 1)
    if checkNumber(t.num) > GoodsUtils.GetThingNo(t.goodsId) then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(t.goodsId)
        GameUtils.Toast(localize("_name_道具不足", {_name_ = vo.name}))
        return
    end

    comp:ActivityNightCatGainUpReq(self._buffId, function()
        self:FillSelf()

        CfUtils.PlayAnimation(self.BuffDisplayNode, "NightCatInstanceBuffDisplayDialogBubbleRightUp")
        if self._cb then
            self._cb()
        end
    end)
end

--卸下
function UINightCatInstanceBuffInfoNode:OnBtnRemove()
    comp:ActivityNightCatGainChangeReq(self._buffId, 1, function()
        self:FillSelf()
        if self._cb then
            self._cb()
        end
    end)
end

--装备
function UINightCatInstanceBuffInfoNode:OnBtnEquip()
    local t = comp:GetEquipBuffInfo()
    local count = 0
    for k, v in pairs(t) do
        if checkNumber(v) > 0 then
            count= count + 1
        end   
    end

    if count >= QuestConfMgr:GetInstance():GetNightCatMaxEquipBuffNum() then
        GameUtils.Toast(localize("装备位置已满"))
        return 
    end
    comp:ActivityNightCatGainChangeReq(self._buffId, 2, function()
        self:FillSelf()
        if self._cb then
            self._cb(true)
        end
    end)
end

function UINightCatInstanceBuffInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UINightCatInstanceBuffInfoNode
